using AfriWallet.Fraud.Signals.Application.Abstractions;using AfriWallet.Fraud.Signals.Application.Commands;using AfriWallet.Fraud.Signals.Application.Services;using AfriWallet.Fraud.Signals.Domain.Enums;using AfriWallet.Fraud.Signals.Infrastructure.Persistence;
static void Assert(bool ok,string name,ref int passed){Console.WriteLine($"{name,-48} {(ok?"PASS":"FAIL")}");if(!ok)throw new InvalidOperationException(name);passed++;}
var passed=0;var now=new DateTimeOffset(2026,8,16,20,0,0,TimeSpan.Zero);var repository=new InMemoryFraudSignalRepository();var audit=new InMemoryFraudSignalAuditStore();var service=new FraudSignalService(repository,audit,new FixedClock(now));var result=await service.RecordAsync(new("evt-payment-001",FraudSignalSource.Payment,FraudSignalType.PaymentAttempted,FraudSignalSeverity.Low,"awid","AWID-TEST-001",now,new Dictionary<string,string>{{"channel","wallet"}}));
Assert(!result.Duplicate,"signal recorded",ref passed);Assert(result.SignalId!=Guid.Empty,"signal id generated",ref passed);var stored=await repository.GetAsync(result.SignalId);Assert(stored is not null,"signal persisted",ref passed);Assert(stored!.Source==FraudSignalSource.Payment,"source preserved",ref passed);Assert(stored.Type==FraudSignalType.PaymentAttempted,"type preserved",ref passed);Assert(stored.Subject.Type=="AWID","subject normalized",ref passed);Assert(stored.Attributes["channel"]=="wallet","attributes preserved",ref passed);var duplicate=await service.RecordAsync(new("EVT-PAYMENT-001",FraudSignalSource.Payment,FraudSignalType.PaymentAttempted,FraudSignalSeverity.Low,"AWID","AWID-TEST-001",now));Assert(duplicate.Duplicate,"duplicate detected",ref passed);var subjectSignals=await repository.GetBySubjectAsync("AWID","AWID-TEST-001");Assert(subjectSignals.Count==1,"duplicate not persisted",ref passed);Assert(audit.Events.Count==1,"audit event recorded",ref passed);var device=await service.RecordAsync(new("evt-device-001",FraudSignalSource.Device,FraudSignalType.NewDevice,FraudSignalSeverity.Medium,"DEVICE","device-sandbox-001",now,new Dictionary<string,string>{{"environment","sandbox"}}));Assert(!device.Duplicate,"device signal accepted",ref passed);var aml=await service.RecordAsync(new("evt-aml-001",FraudSignalSource.Compliance,FraudSignalType.AmlAlert,FraudSignalSeverity.High,"AWID","AWID-TEST-001",now,new Dictionary<string,string>{{"source","AML"}}));Assert(!aml.Duplicate,"AML signal consumed without AML duplication",ref passed);Console.WriteLine($"\nChecks: {passed}\nPassed: {passed}\nFailed: 0\nSkipped: 0\n");Console.WriteLine("All AFW-DLV-0017.1 fraud signal scenarios passed.");
sealed class FixedClock(DateTimeOffset now):ISystemClock { public DateTimeOffset UtcNow{get;}=now; }